from author_csharp_v2 import *

unit(11,
"متد یک کار نام‌دار با ورودی و خروجی مشخص است. پارامتر نام ورودی در تعریف و آرگومان مقدار ارسال‌شده در فراخوانی است. return مقدار را برمی‌گرداند و اجرای متد را تمام می‌کند؛ void یعنی مقدار بازگشتی ندارد. پارامتر مقداری کپی می‌شود، پس تغییر int محلی، متغیر فراخواننده را عوض نمی‌کند. محدودهٔ نام با بلوک و طول عمر محل نگهداری با اجرا مرتبط است؛ این دو یکی نیستند. local function متدی درون متد است. overloadها نام مشترک و امضای پارامتر متفاوت دارند؛ تفاوت نوع خروجی به‌تنهایی کافی نیست. آرگومان نام‌دار خوانایی می‌دهد و پارامتر اختیاری مقدار پیش‌فرض دارد. شکل => برای بدنهٔ تک‌عبارتی است.",
'Console.WriteLine(Total(4, 3));\nstatic int Total(int price, int count = 1) => price * count;', '12',
("دو متد با نام و پارامترهای یکسان، فقط با خروجی int و string چه وضعی دارند؟", "این overload مجاز نیست.", "کامپایلر همیشه خروجی int را ترجیح می‌دهد.", "نام متغیر مقصد به‌تنهایی امضا را متفاوت می‌کند.", "امضای overload به نوع خروجی تنها متکی نیست؛ پارامترها باید تفاوت مجاز داشته باشند."),
analogy("پارامتر و آرگومان", "جفت مرجع: تعریف متد به پارامتر. جفت دوم را با رابطهٔ «محل معرفی دادهٔ ورودی» بساز.", ["محل معرفی ورودی", "ترتیب زمانی", "فراخوانی متد", "آرگومان", "return", "مقدار خروجی"], [[0,2,3]]),
"محاسبهٔ مبلغ را به Total و نمایش را به Console.WriteLine جدا کن. پارامتر تعداد پیش‌فرض 1 باشد. فراخوانی نام‌دار برای قیمت 5 و تعداد 4 و فراخوانی بدون تعداد را تست کن.",
'Console.WriteLine(Total(count:4, price:5));\nConsole.WriteLine(Total(5));\nstatic int Total(int price,int count=1)\n{\n    if(price<0 || count<1) throw new ArgumentOutOfRangeException();\n    return checked(price*count);\n}',
"خروجی‌ها 20 و 5 باشند. محاسبه به Console وابسته نباشد؛ مقدار نامعتبر رد و سرریز پنهان نشود.")
UNITS[11]["game"]["Explanation"] = "در تعریف متد، نام ورودی «پارامتر» است؛ در فراخوانی، مقدار یا عبارت ارسال‌شده «آرگومان» است. پس جفت دوم، فراخوانی متد و آرگومان است. رابطه، نقش ورودی در جایگاه تعریف یا فراخوانی است."

unit(12,
"ref محل متغیر فراخواننده را در اختیار متد می‌گذارد و پیش از فراخوانی باید مقدار داشته باشد. out هم محل را می‌دهد اما متد موظف است در تمام مسیرهای بازگشت مقدارش را بنویسد؛ فراخواننده لازم نیست از قبل مقدار بدهد. in دسترسی فقط‌خواندنی به پارامتر می‌دهد و وعدهٔ تغییرناپذیری عمیق دادهٔ مرجعی نیست. discard با _ خروجی نخواسته را کنار می‌گذارد. params آرایه‌ای تعداد متغیری آرگومان را در یک آرایه می‌گیرد. آرگومان‌ها از چپ به راست ارزیابی می‌شوند، حتی اگر نام‌دار باشند. overload فقط بر تفاوت ref و out مجاز نیست؛ انتخاب قرارداد باید از معنای ورودی‌وخروجی بیاید.",
'int value=2;\nAdd(ref value);\nConsole.WriteLine(value);\nstatic void Add(ref int n) { n+=3; }', '5',
("در TryRead با return false هم پارامتر out باید چه شود؟", "پیش از return مقدار بگیرد.", "بدون انتساب رها شود.", "فقط در مسیر true نوشته شود.", "out قرارداد definite assignment دارد و در تمام بازگشت‌های عادی باید نوشته شود."),
repair("کلید قرارداد خروجی", "متد باید result را پیش از بازگشت بنویسد و فراخواننده بدون مقدار قبلی آن را دریافت کند.", ["ref", "out", "in"], [0], ["نیاز به مقدار قبلی ندارد", "نوشتن result مجاز است"], [([0],[False,True]),([1],[True,True]),([2],[False,False])], code="static bool TryValue(MODE int result) { result=7; return true; }"),
"متد TryPositive را برای متن عدد مثبت بنویس. برای ورودی 3 موفق و برای 0 و متن خراب ناموفق باشد؛ در شکست out صفر شود. تفاوت آن را با ref توضیح بده.",
'foreach(string text in new[]{"3","0","bad"})\n{\n    bool ok=TryPositive(text,out int value);\n    Console.WriteLine($"{ok},{value}");\n}\nstatic bool TryPositive(string text,out int value)\n{\n    value=0;\n    if(!int.TryParse(text,out int parsed) || parsed<=0) return false;\n    value=parsed; return true;\n}',
"خروجی‌ها True,3 و False,0 و False,0 باشند. همهٔ مسیرها out را مقدار دهند و شکست مقدار قبلی را نشت ندهد.")

unit(13,
"null یعنی نبود مقدار مرجعی و با صفر یا متن خالی یکی نیست. int? یک nullable value type است که یا عدد دارد یا ندارد؛ HasValue وضعیت را می‌گوید و Value در حالت نبودن exception می‌دهد. string? در پروژهٔ دارای nullable context امکان نبود رشته را بیان می‌کند. ?. فقط در صورت غیرnull بودن سمت چپ عضو را می‌خواند؛ نتیجه ممکن است nullable شود. ?? مقدار جایگزین را فقط برای null انتخاب می‌کند، نه برای صفر یا متن خالی. ??= فقط در صورت null بودن متغیر را مقداردهی می‌کند. بررسی null باید پیش از دسترسی انجام شود؛ علامت ? در اعلان خودش خطای ورودی را درمان نمی‌کند.",
'int? score=null;\nConsole.WriteLine(score ?? 9);\nscore=0;\nConsole.WriteLine(score ?? 9);', '9\n0',
("اگر int? n برابر صفر باشد، n ?? 5 چه می‌دهد؟", "0", "5", "exception به دلیل صفر بودن", "?? فقط نبود مقدار را جایگزین می‌کند؛ صفر یک مقدار معتبر است."),
experiment("آزمایش نبود مقدار", "نتیجه‌ها آماده‌اند. یک آزمایش باز کن و قانونی را انتخاب کن که هر سه حالت را توضیح می‌دهد.", ["null ?? 5 = 5", "0 ?? 5 = 0، برای int? دارای صفر", '"" ?? "x" = ""'], ["?? تنها null را جایگزین می‌کند.", "?? صفر و رشتهٔ خالی را هم حذف می‌کند.", "?? همیشه سمت راست را برمی‌گرداند."], 0),
"قیمت اختیاری int? را برای null،0،7 پردازش کن. نبود قیمت با Missing نمایش داده شود و صفر به صورت عدد 0 باقی بماند. هرگز Value را بدون بررسی نخوان.",
'foreach(int? price in new int?[]{null,0,7})\n    Console.WriteLine(price.HasValue ? price.Value.ToString() : "Missing");',
"سه خروجی Missing،0،7 باشند. نبود مقدار با صفر مخلوط نشود و مسیر null exception ندهد.")

unit(14,
"Console.ReadLine یک خط متن یا هنگام پایان ورودی null می‌دهد. Parse متن معتبر را به عدد تبدیل می‌کند اما متن خراب می‌تواند exception بدهد؛ TryParse موفقیت را با bool و عدد را با out می‌دهد. Convert برای برخی ورودی‌ها قرارداد متفاوت دارد، از جمله null، پس جایگزین بی‌فکر Parse نیست. culture تعیین می‌کند جداکنندهٔ اعشار و قالب ورودی چه باشد؛ برای قرارداد فایل یا ماشین معمولاً InvariantCulture را صریح انتخاب می‌کنیم. guard clause ورودی نامعتبر را زود برمی‌گرداند تا مسیر اصلی روشن بماند. تلاش مجدد نباید پایان ورودی را به حلقهٔ بی‌پایان تبدیل کند. مرز معتبر باید روشن باشد: قیمت صفر با تعداد صفر الزاماً یک قرارداد ندارد.",
'bool ok=int.TryParse("12",out int number);\nConsole.WriteLine($"{ok},{number}");', 'True,12',
("ReadLine مقدار null داده است. برنامهٔ ورودی‌محور چه کند؟", "پایان ورودی را مدیریت و از حلقه خارج شود.", "تا ابد دوباره ReadLine بخواند.", "null را همیشه همان عدد صفر معتبر بداند.", "پایان ورودی یک وضعیت مستقل است؛ تکرار بی‌پایان راه اصلاح داده نیست."),
mission("دروازهٔ قیمت", "جریان ورودی قیمت را بدون گیرکردن و با پذیرش صفر طراحی کن.", [("ReadLine برابر null است.","خروج با وضعیت پایان ورودی","تلاش مجدد بی‌پایان"),("در اجرای تازه، متن 0 خوانده شده و TryParse موفق است.","بررسی price >= 0","رد صفر بدون بررسی قرارداد"),("قیمت صفر معتبر است.","پذیرش و پایان این ورودی","تبدیل صفر به نبود مقدار")]),
"متد TryPrice با culture ثابت بنویس: null و متن خراب و عدد منفی رد شوند؛ 0 و 12.50 پذیرفته شوند. یک حلقهٔ کنسول هم بنویس که در پایان ورودی خارج شود.",
'using System.Globalization;\nforeach(string? text in new string?[]{null,"bad","-1","0","12.50"})\n    Console.WriteLine(TryPrice(text,out decimal price) ? price.ToString(CultureInfo.InvariantCulture) : "Invalid");\nstatic bool TryPrice(string? text,out decimal price)\n{\n    price=0;\n    if(!decimal.TryParse(text,NumberStyles.Number,CultureInfo.InvariantCulture,out decimal n) || n<0) return false;\n    price=n; return true;\n}',
"خروجی سه Invalid و سپس 0 و 12.50 یا نمایش عددی معادل باشد. null باعث حلقهٔ بی‌پایان نشود؛ culture صریح و مقدار شکست صفر باشد.")

unit(15,
"خطای compile پیش از اجرا مانع ساخت می‌شود؛ خطای runtime هنگام اجرای مسیر مسئله‌دار رخ می‌دهد؛ خطای logic خروجی نادرست بدون الزاماً exception می‌سازد. breakpoint اجرای دیباگر را متوقف، step حرکت بعدی را کنترل و watch مقدارها را نشان می‌دهد. stack trace زنجیرهٔ فراخوانی‌ها را برای پیدا کردن محل خطا نگه می‌دارد. try محدودهٔ عملیات قابل شکست و catch رسیدگی به نوع مشخص خطاست. finally برای cleanup حتی پس از خطا اجرا می‌شود، با استثناهای پایان شدید فرایند. throw; همان خطا را با trace اصلی بازمی‌پرتابد؛ catch خالی یا تبدیل بی‌دلیل همهٔ خطاها به موفقیت، اشکال را پنهان می‌کند. assert انتظار برنامه‌نویس را بررسی می‌کند و جای validation ورودی نیست.",
'int total=0;\nfor(int i=1;i<3;i++) total+=i;\nConsole.WriteLine(total);', '3',
("برنامه باید 1 تا 3 را جمع کند، اما 3 چاپ می‌کند. نوع خطا چیست؟", "خطای منطق در شرط حلقه", "خطای کامپایل", "خطای شبکه", "کد اجرا می‌شود اما i<3 عدد 3 را وارد جمع نمی‌کند؛ breakpoint و watch این مرز را آشکار می‌کنند."),
questions("تشخیص دستهٔ خطا", "هدف ثابت این دور یک نوع خطاست. از نشانه‌های آماده علت را تشخیص بده.", ["خطای کامپایل","خطای زمان اجرا","خطای منطق"], ["آیا build موفق است؟","آیا اجرای مسیر exception می‌دهد؟"], [[False,False],[True,True],[True,False]], 2, limit=2),
"متد جمع 1 تا n را با شرط اشتباه بساز؛ برای n=3 انتظار 6 را با assert بررسی کن. سپس شرط را اصلاح کن. جداگانه FormatException ورودی خراب را محدود catch کن و finally را مشاهده کن.",
'int n=3,total=0;\nfor(int i=1;i<=n;i++) total+=i;\nif(total!=6) throw new Exception("sum failed");\nConsole.WriteLine(total);\ntry { _=int.Parse("bad"); }\ncatch(FormatException) { Console.WriteLine("format"); }\nfinally { Console.WriteLine("cleanup"); }',
"جمع اصلاح‌شده 6 باشد؛ نسخهٔ خراب assert را رد کند. فقط خطای قابل رسیدگی catch و cleanup در هر مسیر انجام شود.")

unit(16,
"فایل csproj نوع SDK، TargetFramework و referenceها را مشخص می‌کند؛ solution چند پروژه را گروه می‌کند. namespace نام‌ها را سازمان می‌دهد و خودش وابستگی پروژه نمی‌سازد. using نام کوتاه، alias نام جایگزین و static using دسترسی مستقیم به عضو static می‌دهد. global using برای فایل‌های پروژه و implicit using از تنظیم SDK می‌آیند. nameof نام نماد را به متن تبدیل می‌کند و با تغییر نام امن‌تر از رشتهٔ دستی است. restore بسته‌ها را آماده می‌کند؛ ProjectReference وابستگی پروژه و PackageReference وابستگی NuGet است. Debug و Release پیکربندی ساخت‌اند؛ global.json نسخهٔ SDK را انتخاب می‌کند. file-based app در .NET 10 با دستورهای #: مثل #:sdk یا #:package تنظیم می‌شود؛ این‌ها با #if شرطی یکی نیستند.",
'using Number = System.Int32;\nNumber count=3;\nConsole.WriteLine(nameof(count));', 'count',
("using Tools; به‌تنهایی چه چیزی را تضمین نمی‌کند؟", "وجود reference به پروژه یا بستهٔ Tools", "امکان نوشتن نام کوتاه نوع موجود در namespace", "خواناتر شدن نام‌های یک namespace موجود", "using فقط حل نام را تغییر می‌دهد؛ وابستگی باید در csproj یا ابزار مناسب تعریف شود."),
constraints("ساخت چندپروژه‌ای", "کتابخانه و مصرف‌کننده ساخته شده‌اند. ترتیب کارها را با قیدهای واقعی آماده‌سازی کن؛ دو ویرایش مستقل می‌توانند جابه‌جا شوند.", ["افزودن ProjectReference", "نوشتن نوع کتابخانه", "نوشتن مصرف‌کننده با namespace صحیح", "dotnet restore", "dotnet build -c Release"], [[0,3],[1,4],[2,4],[3,4]]),
"در solution یک کتابخانهٔ محاسبه و یک console مصرف‌کننده بساز. namespace فایل‌محور، alias و nameof را به کار ببر. مسیر ProjectReference و TFM را در گزارش ساخت مشخص کن.",
'using Calc = Demo.Calculator;\nConsole.WriteLine(Calc.Add(2,5));\nConsole.WriteLine(nameof(Calc));\nnamespace Demo\n{\n    public static class Calculator { public static int Add(int a,int b)=>a+b; }\n}',
"مصرف‌کننده 7 چاپ کند؛ وابستگی در csproj صریح باشد. نمونهٔ مرجع برای اجرای تک‌فایلی namespace بلوکی دارد؛ در پروژهٔ کتابخانه Calculator را در فایل مستقل با namespace Demo; قرار بده.")

unit(17,
"Trim فاصله‌های لبه را حذف می‌کند؛ Split رشته را به بخش‌ها و Join بخش‌ها را به متن تبدیل می‌کند. Replace و برش متن نتیجهٔ تازه می‌سازند. برای شناسه یا پروتکل از StringComparison.Ordinal یا OrdinalIgnoreCase استفاده کن؛ مقایسهٔ زبانی برای متن انسانی هدف دیگری دارد. culture را در parse و format دادهٔ قراردادی صریح کن. StringBuilder برای ساخت تدریجی متن با تغییرهای متعدد مناسب است؛ هر اتصال کوچک الزاماً به آن نیاز ندارد. string از واحدهای UTF-16 تشکیل شده؛ یک emoji ممکن است Length دو داشته باشد و char به‌تنهایی همیشه یک نویسهٔ کامل انسانی نیست. پیش از parse قرارداد جداکننده و فاصله‌های مجاز را مشخص کن.",
'string text=" a , b ";\nstring[] parts=text.Split(\',\',StringSplitOptions.TrimEntries);\nConsole.WriteLine(string.Join("|",parts));', 'a|b',
("برای مقایسهٔ شناسهٔ API بدون تفاوت حروف کدام روشن‌تر است؟", "StringComparison.OrdinalIgnoreCase", "وابسته کردن نتیجه به زبان فعلی دستگاه", "تبدیل char به عدد و جمع آن‌ها", "OrdinalIgnoreCase سیاست مقایسهٔ شناسه را مستقل از culture خواننده مشخص می‌کند."),
pipeline("پاک‌سازی یک ورودی", "ورودی \" A \" باید به \"a\" برسد. Trim و تبدیل حروف مستقل از فرهنگ قابل جابه‌جایی‌اند؛ افزودن براکت مسیر انحرافی است.", ["Trim", "ToLowerInvariant", "افزودن براکت"], ['" A "','"A"','" a "','"a"','"[ A ]"'], [[1,2,4],[1,3,-1],[3,2,-1],[3,3,-1],[-1,-1,-1]], [3], limit=3),
"ورودی ' red , BLUE ,, ' را به نام‌های غیرخالی و پاک‌شده تبدیل کن و با | به هم بچسبان. BLUE را با مقایسهٔ OrdinalIgnoreCase شناسایی کن؛ متن ورودی اولیه محفوظ بماند.",
'string source=" red , BLUE ,, ";\nstring[] parts=source.Split(\',\',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries);\nConsole.WriteLine(string.Join("|",parts));\nConsole.WriteLine(string.Equals(parts[1],"blue",StringComparison.OrdinalIgnoreCase));\nConsole.WriteLine(source);',
"خروجی red|BLUE و True باشد. خانه‌های خالی حذف شوند، منبع تغییر نکند و مقایسه وابسته به فرهنگ جاری نباشد.")

unit(18,
"enum نام‌های مرتبط را روی یک نوع عددی زیرین قرار می‌دهد؛ cast عدد به enum تضمین نمی‌کند نام یا ترکیب مجاز باشد. برای Flags مقدارهای مستقل معمولاً توان‌های دو هستند و صفر معنی None دارد. | بیت‌ها را ترکیب، & اشتراک، ^ تفاوت و ~ وارونگی می‌دهد. shift بیت‌ها را جابه‌جا می‌کند؛ >>> راست‌شیفت بدون گسترش علامت است. [Flags] یک Attribute آماده برای بیان قصد و نمایش است، نه نگهبان خودکار اعتبار. برای اعتبار ترکیب، بیت ناشناخته را با ماسک بررسی کن. عملگر & روی عدد بیتی است و با && روی bool که short-circuit دارد تفاوت دارد.",
'int read=1,write=2;\nint both=read|write;\nConsole.WriteLine(both);\nConsole.WriteLine((both & write)!=0);', '3\nTrue',
("آیا [Flags] cast مقدار 8 به enum دارای Read=1 و Write=2 را رد می‌کند؟", "خیر؛ اعتبار بیت‌ها را باید جدا بررسی کرد.", "بله؛ همهٔ بیت‌های نامعتبر خودکار exception می‌دهند.", "بله؛ فقط عدد صفر قابل cast است.", "Attribute قصد استفاده را بیان می‌کند؛ برای اعتبار باید (value & ~allowed)==0 بررسی شود."),
counter("بیت ناشناخته", "ادعا: تمام عددهای مثبت، ترکیب مجاز Read=1 و Write=2 هستند.", ["مقدار 1","مقدار 3","مقدار 4"], [("Read معتبر","معتبر",False,"بیت Read تعریف شده است."),("Read و Write معتبر","معتبر",False,"ترکیب هر دو بیت مجاز است."),("بیت ناشناخته","معتبر",True,"بیت 4 در ماسک 3 وجود ندارد.")]),
"Flags برای None،Read،Write بساز. مقدارهای 0،3،4 را اعتبارسنجی کن و نتیجهٔ داشتن Read را جدا چاپ کن. بیت ناشناخته رد شود، صفر معتبر بماند.",
'foreach(Access value in new[]{(Access)0,(Access)3,(Access)4})\n{\n    bool valid=(value & ~(Access.Read|Access.Write))==0;\n    Console.WriteLine($"{valid},{(value & Access.Read)!=0}");\n}\n[Flags] enum Access { None=0,Read=1,Write=2 }',
"خروجی‌ها True,False و True,True و False,False باشند. اعتبار فقط با Enum.IsDefined که ترکیب نام‌گذاری‌نشده را رد می‌کند سنجیده نشود.")

unit(19,
"الگوریتم مراحل روشن حل مسئله است. ناوردای حلقه گزاره‌ای است که پیش از شروع و پس از هر دور برقرار می‌ماند؛ همراه شرط پایان، درستی را توضیح می‌دهد. جست‌وجوی خطی تا n خانه را می‌بیند؛ جست‌وجوی دودویی به دادهٔ مرتب نیاز دارد و بازه را تقریباً نصف می‌کند. مرتب‌سازی ساده مثل insertion sort برای فهم جابه‌جایی و هزینه مفید است. بازگشت باید حالت پایه و کاهش مسئله داشته باشد؛ هر ورودی بزرگ برای recursion مناسب نیست. رشد زمان و حافظه از تعداد عملیات و دادهٔ کمکی فهمیده می‌شود، نه از کوتاهی کد. label و goto را در کد قدیمی می‌بینی؛ برای این مسئله حلقه و return روشن‌ترند.",
'int[] values={3,7,9};\nint found=-1;\nfor(int i=0;i<values.Length;i++) if(values[i]==7) {found=i;break;}\nConsole.WriteLine(found);', '1',
("پیش‌شرط جست‌وجوی دودویی معمول چیست؟", "مرتب بودن داده با همان مقایسه‌گر", "حداقل هزار عنصر", "وجود حتمی مقدار هدف", "نصف‌کردن بازه فقط با ترتیب سازگار می‌تواند بخش ناممکن را کنار بگذارد."),
spectrum("بدترین جست‌وجوی خطی", "در آرایهٔ 8عضوی، مقدار هدف وجود ندارد و هر خانه یک بار مقایسه می‌شود.", "معیار فقط تعداد مقایسهٔ عنصر با هدف است. تلورانس آموزشی یک مقایسه در دو طرف مقدار دقیق 8 است.", 0, 16, 7, 9, ["آرایهٔ خالی: 0 مقایسه", "یک عنصر نامنطبق: 1 مقایسه"]),
"جست‌وجوی خطی را در متدی بنویس که نبود مقدار را با -1 اعلام کند. خالی، تک‌عضوی، اولین و آخرین خانه را تست کن و ناوردای بخش بررسی‌شده را بنویس.",
'Console.WriteLine(Find(Array.Empty<int>(),2));\nConsole.WriteLine(Find(new[]{2},2));\nConsole.WriteLine(Find(new[]{1,3,5},5));\nstatic int Find(int[] values,int target)\n{\n    for(int i=0;i<values.Length;i++) if(values[i]==target) return i;\n    return -1;\n}',
"نتیجه‌ها -1،0،2 باشند. پیش از هر دور، target در خانه‌های قبلی یافت نشده باشد؛ بدترین زمان خطی و حافظهٔ کمکی ثابت توضیح داده شود.")

unit(20,
"پروژهٔ مبانی باید مفاهیم قبلی را در یک رفتار کامل جمع کند. منو ورودی را می‌خواند، اعتبارسنجی می‌کند و فرمان را به متد مناسب می‌دهد. محاسبه از نمایش جدا می‌ماند تا با دادهٔ ثابت بررسی شود. EOF، فرمان خروج و ورودی خراب سه مسیر مستقل‌اند. آرایهٔ خالی، تکرار فرمان و صفر باید قرارداد مشخص داشته باشند. نام متد باید کارش را نشان دهد و تابع محاسبه نباید بی‌دلیل از Console بخواند. پیش از افزودن قابلیت تازه، مسیر خروج و رد ورودی را قدم‌به‌قدم ردگیری کن؛ برنامه‌ای که فقط مسیر درست را دارد کامل نیست.",
'Console.WriteLine(Sum(new[]{2,4,6}));\nstatic int Sum(int[] values) { int total=0; foreach(int n in values) total+=n; return total; }', '12',
("برای تست محاسبهٔ دفتر امتیاز کدام مرز مناسب‌تر است؟", "متد دریافت‌کنندهٔ آرایه و برگردانندهٔ نتیجه", "متدی که همیشه از کاربر واقعی ورودی می‌خواند", "ذخیرهٔ نتیجه فقط در یک پیام چاپی", "جداسازی محاسبه از ورودی‌وخروجی تست را قابل تکرار می‌کند."),
budget("حداقل دفتر امتیاز", "بودجه هزینهٔ فرضی توسعه است. طرحی انتخاب کن که ورودی نامعتبر و EOF و محاسبهٔ مستقل را پوشش دهد.", ["TryParse و guard", "رسیدگی EOF", "متد Sum مستقل", "سه قابلیت تزئینی"], [1,1,1,4], [["اعتبار"],["پایان"],["محاسبه"],[]], ["اعتبار","پایان","محاسبه"], 3, [0,1,2]),
"ماشین‌حساب منودار بساز: دستور sum مجموع [2,4,6]، دستور exit خروج، ورودی دیگر پیام Unknown بدهد. پایان ورودی هم برنامه را تمام کند. Sum جداگانه با آرایهٔ خالی تست شود.",
'while(true)\n{\n    string? command=Console.ReadLine();\n    if(command is null || command=="exit") break;\n    if(command=="sum") Console.WriteLine(Sum(new[]{2,4,6}));\n    else Console.WriteLine("Unknown");\n}\nstatic int Sum(int[] values) { int total=0; foreach(int n in values) total=checked(total+n); return total; }',
"دادهٔ هدایت‌شدهٔ bad سپس sum سپس exit به Unknown و 12 برسد. EOF بدون خروجی اضافی پایان دهد. آرایهٔ خالی صفر بدهد و منطق مستقل باشد.")
